PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE _mocha_migrations (
number     INTEGER UNIQUE,
up_sql     TEXT NOT NULL,
down_sql   TEXT NOT NULL,
applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE users (
id INTEGER PRIMARY KEY AUTOINCREMENT,
name TEXT NOT NULL,
username TEXT NOT NULL UNIQUE,
password_hash TEXT NOT NULL,
is_admin BOOLEAN NOT NULL DEFAULT 0,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, role TEXT NOT NULL DEFAULT 'colaborador');
CREATE TABLE checklists (
id INTEGER PRIMARY KEY AUTOINCREMENT,
user_id INTEGER NOT NULL,
vehicle_type TEXT NOT NULL,
brand_model TEXT NOT NULL,
license_plate TEXT NOT NULL,
initial_observations TEXT,
client_signature_key TEXT,
collaborator_signature_key TEXT,
is_completed BOOLEAN NOT NULL DEFAULT 0,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, odometer INTEGER, os_ready BOOLEAN NOT NULL DEFAULT 0, equipment_category TEXT NOT NULL DEFAULT 'vehicle', equipment_identifier TEXT, os_opened_at DATETIME, os_opened_by_user_id INTEGER, os_number TEXT);
CREATE TABLE checklist_photos (
id INTEGER PRIMARY KEY AUTOINCREMENT,
checklist_id INTEGER NOT NULL,
photo_type TEXT NOT NULL,
r2_key TEXT NOT NULL,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE checklist_videos (
id INTEGER PRIMARY KEY AUTOINCREMENT,
checklist_id INTEGER NOT NULL,
r2_key TEXT NOT NULL,
duration_seconds INTEGER,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE notifications (
id INTEGER PRIMARY KEY AUTOINCREMENT,
user_id INTEGER NOT NULL,
checklist_id INTEGER NOT NULL,
message TEXT NOT NULL,
is_read BOOLEAN NOT NULL DEFAULT 0,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, notification_type TEXT NOT NULL DEFAULT 'checklist_completed');
CREATE TABLE chat_messages (
id INTEGER PRIMARY KEY AUTOINCREMENT,
from_user_id INTEGER NOT NULL,
to_user_id INTEGER NOT NULL,
checklist_id INTEGER,
message TEXT NOT NULL,
is_read BOOLEAN NOT NULL DEFAULT 0,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE fleet_checklists (
id INTEGER PRIMARY KEY AUTOINCREMENT,
user_id INTEGER NOT NULL,
checklist_type TEXT NOT NULL DEFAULT 'saida',
driver_name TEXT NOT NULL,
inspection_date DATETIME NOT NULL,
vehicle TEXT NOT NULL,
company TEXT NOT NULL,
general_condition TEXT,
rear_lights TEXT,
front_lights TEXT,
safety_items TEXT,
motor_items TEXT,
observations TEXT,
signature_key TEXT,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, driver_signature_key TEXT, inspector_signature_key TEXT, left_side_photo_key TEXT, right_side_photo_key TEXT, front_photo_key TEXT, rear_photo_key TEXT, interior_photo_key TEXT, km_initial INTEGER, km_final INTEGER, interior_clean_approved BOOLEAN, vehicle_id INTEGER);
CREATE TABLE fleet_damage_marks (
id INTEGER PRIMARY KEY AUTOINCREMENT,
checklist_id INTEGER NOT NULL,
vehicle_side TEXT NOT NULL,
x_position REAL NOT NULL,
y_position REAL NOT NULL,
observation TEXT,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE fleet_damage_photos (
id INTEGER PRIMARY KEY AUTOINCREMENT,
damage_mark_id INTEGER NOT NULL,
r2_key TEXT NOT NULL,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE vehicles (
id INTEGER PRIMARY KEY AUTOINCREMENT,
license_plate TEXT NOT NULL,
model TEXT NOT NULL,
is_active BOOLEAN DEFAULT 1,
created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_users_username ON users(username);
CREATE INDEX idx_users_is_admin ON users(is_admin);
CREATE INDEX idx_checklists_user_id ON checklists(user_id);
CREATE INDEX idx_checklists_license_plate ON checklists(license_plate);
CREATE INDEX idx_checklists_created_at ON checklists(created_at);
CREATE INDEX idx_checklist_photos_checklist_id ON checklist_photos(checklist_id);
CREATE INDEX idx_checklist_videos_checklist ON checklist_videos(checklist_id);
CREATE INDEX idx_notifications_user_id ON notifications(user_id);
CREATE INDEX idx_notifications_checklist_id ON notifications(checklist_id);
CREATE INDEX idx_chat_messages_from_user ON chat_messages(from_user_id);
CREATE INDEX idx_chat_messages_to_user ON chat_messages(to_user_id);
CREATE INDEX idx_chat_messages_checklist ON chat_messages(checklist_id);
CREATE INDEX idx_fleet_checklists_user ON fleet_checklists(user_id);
CREATE INDEX idx_fleet_checklists_date ON fleet_checklists(inspection_date);
CREATE INDEX idx_fleet_checklists_vehicle ON fleet_checklists(vehicle);
CREATE INDEX idx_fleet_checklists_company ON fleet_checklists(company);
CREATE INDEX idx_fleet_damage_marks_checklist ON fleet_damage_marks(checklist_id);
CREATE INDEX idx_fleet_damage_photos_mark ON fleet_damage_photos(damage_mark_id);
CREATE INDEX idx_vehicles_license_plate ON vehicles(license_plate);
