INSERT INTO "_mocha_migrations" ("number","up_sql","down_sql","applied_at") VALUES(5,replace('\n-- Add role to users table (admin, colaborador, recepcao)\nALTER TABLE users ADD COLUMN role TEXT NOT NULL DEFAULT ''colaborador'';\n\n-- Add odometer to checklists table\nALTER TABLE checklists ADD COLUMN odometer INTEGER;\n\n-- Add O.S. ready status to checklists table\nALTER TABLE checklists ADD COLUMN os_ready BOOLEAN NOT NULL DEFAULT 0;\n\n-- Create notifications table\nCREATE TABLE notifications (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  user_id INTEGER NOT NULL,\n  checklist_id INTEGER NOT NULL,\n  message TEXT NOT NULL,\n  is_read BOOLEAN NOT NULL DEFAULT 0,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX idx_notifications_user_id ON notifications(user_id);\nCREATE INDEX idx_notifications_checklist_id ON notifications(checklist_id);\n\n-- Create chat messages table\nCREATE TABLE chat_messages (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  from_user_id INTEGER NOT NULL,\n  to_user_id INTEGER NOT NULL,\n  checklist_id INTEGER,\n  message TEXT NOT NULL,\n  is_read BOOLEAN NOT NULL DEFAULT 0,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX idx_chat_messages_from_user ON chat_messages(from_user_id);\nCREATE INDEX idx_chat_messages_to_user ON chat_messages(to_user_id);\nCREATE INDEX idx_chat_messages_checklist ON chat_messages(checklist_id);\n','\n',char(10)),replace('\nDROP INDEX idx_chat_messages_checklist;\nDROP INDEX idx_chat_messages_to_user;\nDROP INDEX idx_chat_messages_from_user;\nDROP TABLE chat_messages;\n\nDROP INDEX idx_notifications_checklist_id;\nDROP INDEX idx_notifications_user_id;\nDROP TABLE notifications;\n\nALTER TABLE checklists DROP COLUMN os_ready;\nALTER TABLE checklists DROP COLUMN odometer;\nALTER TABLE users DROP COLUMN role;\n','\n',char(10)),'2026-02-09 12:21:59');
