INSERT INTO "_mocha_migrations" ("number","up_sql","down_sql","applied_at") VALUES(7,replace('-- Add notification type tracking\nALTER TABLE notifications ADD COLUMN notification_type TEXT NOT NULL DEFAULT ''checklist_completed'';\n\n-- Add OS tracking fields to checklists\nALTER TABLE checklists ADD COLUMN os_opened_at DATETIME;\nALTER TABLE checklists ADD COLUMN os_opened_by_user_id INTEGER;\nALTER TABLE checklists ADD COLUMN os_number TEXT;\n\n-- Create notification settings table (by role)\nCREATE TABLE notification_settings (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  role TEXT NOT NULL,\n  notification_type TEXT NOT NULL,\n  is_enabled BOOLEAN NOT NULL DEFAULT 1,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  UNIQUE(role, notification_type)\n);\n\n-- Insert default notification settings for each role\nINSERT INTO notification_settings (role, notification_type, is_enabled) VALUES\n-- Recepção receives checklist completed notifications\n(''recepcao'', ''checklist_completed'', 1),\n(''recepcao'', ''os_opened'', 0),\n(''recepcao'', ''checklist_edited'', 0),\n(''recepcao'', ''checklist_deleted'', 0),\n\n-- Colaborador receives OS opened notifications (for their own checklists)\n(''colaborador'', ''checklist_completed'', 0),\n(''colaborador'', ''os_opened'', 1),\n(''colaborador'', ''checklist_edited'', 1),\n(''colaborador'', ''checklist_deleted'', 1),\n\n-- Admin receives all by default\n(''admin'', ''checklist_completed'', 1),\n(''admin'', ''os_opened'', 1),\n(''admin'', ''checklist_edited'', 1),\n(''admin'', ''checklist_deleted'', 1);','\n',char(10)),replace('-- Remove notification settings\nDROP TABLE notification_settings;\n\n-- Remove OS tracking fields from checklists\nALTER TABLE checklists DROP COLUMN os_number;\nALTER TABLE checklists DROP COLUMN os_opened_by_user_id;\nALTER TABLE checklists DROP COLUMN os_opened_at;\n\n-- Remove notification type from notifications\nALTER TABLE notifications DROP COLUMN notification_type;','\n',char(10)),'2026-03-20 13:39:22');
INSERT INTO "_mocha_migrations" ("number","up_sql","down_sql","applied_at") VALUES(8,replace('-- Store push notification subscriptions for each user''s device\nCREATE TABLE push_subscriptions (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  user_id INTEGER NOT NULL,\n  endpoint TEXT NOT NULL,\n  p256dh_key TEXT NOT NULL,\n  auth_key TEXT NOT NULL,\n  user_agent TEXT,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX idx_push_subscriptions_user_id ON push_subscriptions(user_id);\nCREATE UNIQUE INDEX idx_push_subscriptions_endpoint ON push_subscriptions(endpoint);','\n',char(10)),replace('DROP INDEX idx_push_subscriptions_endpoint;\nDROP INDEX idx_push_subscriptions_user_id;\nDROP TABLE push_subscriptions;','\n',char(10)),'2026-03-20 13:57:39');
INSERT INTO "_mocha_migrations" ("number","up_sql","down_sql","applied_at") VALUES(9,replace('\n-- Drop push notification tables\nDROP TABLE IF EXISTS push_subscriptions;\nDROP TABLE IF EXISTS notification_settings;\n','\n',char(10)),replace('\n-- Recreate notification_settings table\nCREATE TABLE notification_settings (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\nrole TEXT NOT NULL,\nnotification_type TEXT NOT NULL,\nis_enabled BOOLEAN NOT NULL DEFAULT 1,\ncreated_at DATETIME DEFAULT CURRENT_TIMESTAMP,\nupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP,\nUNIQUE(role, notification_type)\n);\n\n-- Recreate push_subscriptions table\nCREATE TABLE push_subscriptions (\nid INTEGER PRIMARY KEY AUTOINCREMENT,\nuser_id INTEGER NOT NULL,\nendpoint TEXT NOT NULL,\np256dh_key TEXT NOT NULL,\nauth_key TEXT NOT NULL,\nuser_agent TEXT,\ncreated_at DATETIME DEFAULT CURRENT_TIMESTAMP,\nupdated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n','\n',char(10)),'2026-05-12 17:23:15');
INSERT INTO "_mocha_migrations" ("number","up_sql","down_sql","applied_at") VALUES(10,replace('\n-- Main fleet checklist table\nCREATE TABLE fleet_checklists (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  user_id INTEGER NOT NULL,\n  checklist_type TEXT NOT NULL DEFAULT ''saida'',\n  driver_name TEXT NOT NULL,\n  inspection_date DATETIME NOT NULL,\n  vehicle TEXT NOT NULL,\n  company TEXT NOT NULL,\n  general_condition TEXT,\n  rear_lights TEXT,\n  front_lights TEXT,\n  safety_items TEXT,\n  motor_items TEXT,\n  observations TEXT,\n  signature_key TEXT,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Damage marks on vehicle images\nCREATE TABLE fleet_damage_marks (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  checklist_id INTEGER NOT NULL,\n  vehicle_side TEXT NOT NULL,\n  x_position REAL NOT NULL,\n  y_position REAL NOT NULL,\n  observation TEXT,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Photos attached to damage marks\nCREATE TABLE fleet_damage_photos (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  damage_mark_id INTEGER NOT NULL,\n  r2_key TEXT NOT NULL,\n  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX idx_fleet_checklists_user ON fleet_checklists(user_id);\nCREATE INDEX idx_fleet_checklists_date ON fleet_checklists(inspection_date);\nCREATE INDEX idx_fleet_checklists_vehicle ON fleet_checklists(vehicle);\nCREATE INDEX idx_fleet_checklists_company ON fleet_checklists(company);\nCREATE INDEX idx_fleet_damage_marks_checklist ON fleet_damage_marks(checklist_id);\nCREATE INDEX idx_fleet_damage_photos_mark ON fleet_damage_photos(damage_mark_id);\n','\n',char(10)),replace('\nDROP INDEX idx_fleet_damage_photos_mark;\nDROP INDEX idx_fleet_damage_marks_checklist;\nDROP INDEX idx_fleet_checklists_company;\nDROP INDEX idx_fleet_checklists_vehicle;\nDROP INDEX idx_fleet_checklists_dat